package org.familyhealthcare.controller;
import org.familyhealthcare.common.Result;import org.familyhealthcare.entity.OperationAuditLog;import org.familyhealthcare.mapper.OperationAuditLogMapper;import org.familyhealthcare.util.CurrentUserUtil;import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.baomidou.mybatisplus.core.metadata.IPage;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/audit-log") public class AuditLogController{@Autowired private OperationAuditLogMapper mapper;@GetMapping("/page")public Result<IPage<OperationAuditLog>> page(@RequestParam(defaultValue="1")long page,@RequestParam(defaultValue="30")long size,@RequestParam(required=false)String path){if(!CurrentUserUtil.isAdmin())return Result.error(403,"onlymanagementmembercan ViewauditDaylog");QueryWrapper<OperationAuditLog> q=new QueryWrapper<>();if(path!=null&&!path.trim().isEmpty())q.like("request_path",path.trim());q.orderByDesc("created_at");return Result.ok(mapper.selectPage(new Page<>(page,Math.min(size,100)),q));}}
